  const other = qa.cur === qa.A ? qa.B : qa.A, url = qaFile(n.abs, n.bism, n.part);
  if(other.src !== url){ other._k = qaKey(n.abs, n.bism); other._v = qaVoiceOf(n.part); other.src = url; other.preload = 'auto'; try{ other.load(); }catch(e){} }
