  const def = TR_LANGS.find(l=>l.k === lang), conv = def.conv === 'roman' ? (x=> devaToRoman(trNabi(trAddr(x), 'rom', s)).replace(/\btumko ko\b/gi, m=> m.slice(0, 5))) : (x=> trNabi(lang === 'hi' ? trAddr(x) : x, lang, s));
