  const S = {};
  S[1] = wrap('#e8f9e8','#9fdc9f',`<circle cx="250" cy="38" r="30" fill="url(#dsl1)"/><circle cx="250" cy="38" r="11" fill="#fff0b3"/><path d="M0 96 Q80 74 160 92 T320 84 V150 H0z" fill="#86cf86"/><path d="M0 112 Q90 100 170 114 T320 108 V150 H0z" fill="#6dbd6d"/><path d="M40 150 Q120 118 210 126 T320 120 V150z" fill="#8fdcf0" opacity=".7"/>${tree(70,92,1.1,'#4fa84f',1)}${tree(160,84,1.5,'#3f9a3f',1)}${tree(250,96,1,'#5cb35c',1)}`,1);
  S[2] = wrap('#1d2a33','#2d4a52',`<ellipse cx="80" cy="26" rx="60" ry="16" fill="#3a4a54"/><ellipse cx="220" cy="20" rx="80" ry="18" fill="#34444e"/><g stroke="#9db6c4" stroke-width="1" opacity=".55">${Array.from({length:26},(_,i)=>`<line x1="${i*13+4}" y1="${30+(i*17)%40}" x2="${i*13-2}" y2="${44+(i*17)%40}"/>`).join('')}</g><g transform="translate(160 92)"><path d="M-52 0h104l-14 14h-76z" fill="#7a4a24"/><rect x="-24" y="-18" width="48" height="18" fill="#a8672f"/><path d="M-28 -18h56l-8 -10h-40z" fill="#8a5224"/><g fill="#ffd36b"><rect x="-17" y="-12" width="6" height="6"/><rect x="-6" y="-12" width="6" height="6"/><rect x="5" y="-12" width="6" height="6"/></g></g><path d="M0 108 q20 -10 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 V150H0z" fill="#27525c"/><path d="M0 124 q20 -8 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 V150H0z" fill="#1d3f48"/>`,2);
