  T.masjidIn = ()=> wrap('#2c3b66','#e6a77d', moon(40, 18, .8) + stars([[90,20],[250,16],[200,38]]) + dome(160, 112, 62, '#1d2644') + minaret(104, 112, 62, '#1d2644') + minaret(216, 112, 62, '#1d2644') + `<rect x="84" y="108" width="152" height="42" fill="#1d2644"/>` + arch(160, 150, 22, 34, '#ffd98a'), 'mIn');
  T.masjidOut = ()=> wrap('#e4f1fb','#fbe7c3', sun(60, 34, 13, 'mOut') + dome(190, 112, 62, '#7fa6a0') + minaret(134, 112, 62, '#7fa6a0') + minaret(246, 112, 62, '#7fa6a0') + `<rect x="114" y="108" width="152" height="42" fill="#7fa6a0"/>` + arch(190, 150, 22, 34, '#fff1c6'), 'mOut');
  T.cloudBreak = ()=> wrap('#cdd8e6','#eef0f4', sun(200, 52, 13, 'cb') + cloud(150, 50, 1.6, '#b7c2d2', .95) + cloud(250, 40, 1.2, '#c4cedb', .9) + `<path d="M190 66 L150 150 H250z" fill="#fff3c4" opacity=".28"/>` + hills('#9bb7a3','#82a08e', 112), 'cb');
  T.heavy = ()=> wrap('#a9b6c8','#d6dce6', cloud(80, 38, 1.8, '#8795ab', .95) + cloud(220, 30, 1.6, '#93a0b4', .95) + cloud(160, 56, 1.3, '#7e8ca3', .9) + hills('#8aa09a','#728a86', 112) + lamp(160, 104, 'hv'), 'hv');
  T.mountain = ()=> wrap('#e0e9f4','#b7c9dd', sun(250, 36, 12, 'mt') + `<path d="M20 120 L120 52 L170 90 L220 44 L310 120z" fill="#7f97b3"/><path d="M120 52 L100 66 L116 62 L124 70 L136 62z" fill="#fff" opacity=".9"/><path d="M220 44 L202 60 L216 58 L224 66 L238 58z" fill="#fff" opacity=".9"/><path d="M0 120 Q80 104 160 116 T320 110 V150 H0z" fill="#6d8aa6"/>`, 'mt');
  T.house = ()=> wrap('#1f3052','#3d5c80', stars(ST) + moon(256, 20, 1) + hills('#223a5a','#1a2e4a', 114) + `<rect x="118" y="82" width="84" height="46" fill="#33486a"/><path d="M110 84 L160 52 L210 84z" fill="#27395a"/><rect x="128" y="94" width="18" height="16" rx="2" fill="#ffd98a"/><rect x="174" y="94" width="18" height="16" rx="2" fill="#ffd98a"/><rect x="153" y="104" width="14" height="24" rx="6" fill="#ffd98a"/>` + tree(80, 112, .9, '#2c5a4a') + tree(244, 114, .8, '#2c5a4a'), 'home');
